import { usePage } from "../contexts.jsx";

export default function BreakingTicker() {
    const page = usePage();
    const lead = page.stages?.[0]?.hero?.[0];
    if (!lead)
        return null;
    return (
        <div className="bg-alert-50 text-sm" role="status">
            <div className="mx-auto flex max-w-(--width-page) items-center gap-3 px-4 py-2">
                <span className="rounded-sm bg-alert-500 px-1.5 py-0.5 text-2xs font-bold text-white uppercase">Eilmeldung</span>
                <a href={lead.path.href} className="truncate font-medium text-alert-700 hover:underline">{lead.headline}</a>
            </div>
        </div>
    );
}
